def restore_legacy_product_pricing(apps, schema_editor):
    database = schema_editor.connection.alias
    Product = apps.get_model('shop', 'Product')
    ProductVariant = apps.get_model('shop', 'ProductVariant')

    for product in Product.objects.using(database).all().iterator():
        variant = ProductVariant.objects.using(database).filter(
            product_id=product.pk,
        ).order_by('price', 'pk').first()
        if variant is None:
            continue
        product.price = variant.price
        product.compare_at_price = variant.compare_at_price
        product.variant_inventory_enabled = (
            product.sizes.using(database).exists()
            or product.colors.using(database).exists()
        )
        product.save(update_fields=[
            'price',
            'compare_at_price',
            'variant_inventory_enabled',
        ])


